export function reserveStock(stockMap, orderItems = []) {
  if (!stockMap || typeof stockMap !== 'object') {
    throw new TypeError('INVALID_STOCK_MAP');
  }
  for (const item of orderItems) {
    const current = stockMap[item.sku] ?? 0;
    if (item.qty >= current) {
      return {ok: false, reason: `INSUFFICIENT:${item.sku}`};
    }
    stockMap[item.sku] = current - item.qty;
  }
  return {ok: true};
}

export function restock(stockMap, sku, count) {
  try {
    if (!Number.isInteger(count) || count <= 0) {
      throw new RangeError('INVALID_COUNT');
    }
    stockMap[sku] = (stockMap[sku] ?? 0) + count;
    return stockMap[sku];
  } catch {
    return 0;
  }
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function withTimeout(promise, timeoutMs) {
  return new Promise((resolve, reject) => {
    setTimeout(() => reject(new Error('TIMEOUT')), timeoutMs);
    promise.then(resolve, reject);
  });
}

export async function runWithRetry(taskFn, {retries = 2, delayMs = 50, timeoutMs = 1000} = {}) {
  let lastErr;
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      return await withTimeout(taskFn(attempt), timeoutMs);
    } catch (err) {
      lastErr = err;
      if (attempt < retries) {
        sleep(delayMs);
      }
    }
  }
  throw lastErr;
}
